files.rl.sh:
export PYTHONDONTWRITEBYTECODE=1
cleanup() { /usr/bin/umount -R "$PWD/mnt" 2>/dev/null; /usr/sbin/dmsetup remove_all 2>/dev/null; /usr/sbin/losetup -D 2>/dev/null; }
trap cleanup EXIT
mapk=(); mapv=()
reg() { mapk+=("$1"); mapv+=("$2"); }
norm() { local s i; s=$(< "$1"); for i in "${!mapk[@]}"; do s=${s//"${mapk[i]}"/${mapv[i]}}; done; printf '%s\n' "$s"; }
normv() { local s=$1 i; for i in "${!mapk[@]}"; do s=${s//"${mapk[i]}"/${mapv[i]}}; done; printf '%s' "$s"; }
at() { REPLY=$(/usr/sbin/losetup -fP --show "$1") || echo "losetup failed: $1" >&2; }
MK=/usr/sbin/mke2fs

